import styled from '@emotion/styled';

export const StyledPillarCard = styled.div({
  width: '158.85714721679688px',
  height: '158.86000061035156px',
  borderRadius: '12px',
  border: 'none',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  padding: '16px',
  cursor: 'pointer',
  transition: 'transform 0.25s ease-in-out',
  '&:hover': {
    transform: 'scale(1.05)',
  },
});

export const StyledTitle = styled.h3({
  fontFamily: 'Barlow',
  fontWeight: '600',
  fontStyle: 'SemiBold',
  fontSize: '16px',
  lineHeight: '120%',
  letterSpacing: '0%',
  verticalAlign: 'middle',
  color: '#0D0D0C',
  margin: '0',
});

export const StyledTotalTrainings = styled.p({
  fontFamily: 'Work Sans',
  fontWeight: '400',
  fontStyle: 'Regular',
  fontSize: '14px',
  lineHeight: '140%',
  letterSpacing: '0%',
  verticalAlign: 'middle',
  color: '#67665F',
  margin: '0',
});
